insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$sao-vicente$q$, $q$https://sapl.saovicente.sp.leg.br/media/sapl/public/normajuridica/2009/5641/lei_a2163.pdf (Lei 2163-A/2009, ARC) ; https://sapl.saovicente.sp.leg.br/media/sapl/public/normajuridica/1990/6149/lei_2320.pdf (Lei 2.320/1990, Ponte Pênsil) ; https://sapl.saovicente.sp.leg.br/media/sapl/public/normajuridica/2025/9410/l4633.pdf (Lei 4.633/2025, revogação de 215 leis)$q$, $q$Leis municipais de São Vicente (SAPL da Câmara): domínio público (Lei 9.610/1998, art. 8º, IV). Geometria: OpenStreetMap (ODbL 1.0, © colaboradores do OpenStreetMap).$q$, 8, $q$A Lei 4.633/2025 revogou 215 leis de trânsito e estacionamento de caminhão; a 2163-A/2009 (ARC), a 2.320/1990 (Ponte Pênsil) e as leis de rua 633-A/1998, 669-A/1998, 1169-A/2002 e 3339-A/2015 não estão na lista. A Lei 633-A/1998 (caminhão com mais de 3 eixos em todas as vias do Jardim Pombeba) não foi registrada: o bairro não tem contorno no OSM.$q$);
